"""Return the index where to insert item x in list a, assuming a is sorted.
    The return value i is such that all e in a[:i] have e <= x, and all e in
    a[i:] have e > x.  So if x already appears in the list, a.insert(x) will
    insert just after the rightmost x already there.
    Optional args lo (default 0) and hi (default len(a)) bound the
    slice of a to be searched.
    """
def bisect_right(a: Any, x: Any, lo: Any = 0, hi: Any = None) -> object {
    if (lo < 0) {
        raise ValueError('lo must be non-negative');
    }
    if (hi is None) {
        hi = len(a);
    }
    while (lo < hi) {
        mid = (lo + hi) // 2;
        if (x < a[mid]) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

"""
    Returns the size ``n`` in human readable form, i.e. as bytes, KB, MB, GB, ...

    :return: human readable size
    """
def show_size(n: Any) -> str {
    _n = n;
    if (_n < 1024) {
        return "{} bytes".format(_n);
    }
    for dim in ['KB', 'MB', 'GB', 'TB', 'PB'] {
        _n = _n / 1024.0;
        if (_n < 1024) {
            return "{:.3f} {}".format(_n, dim);
        }
    }
    return "{} bytes".format(n);
}

